package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied or defaulted to today) must fall on a
        // business day; a weekend rolls forward to the next Monday.
        owner.setRegistrationDate(BusinessDay.effective(request));
        built.set(owner);
    }
}
===== ValidateOwnerFields.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a create whose firstName, lastName,
 * address, city or telephone is missing or blank with a 400 whose {@code errors} array
 * names each offending field. Bean validation still runs first (via {@code @Valid}) so
 * pattern/size failures keep their existing behaviour; this step additionally catches
 * whitespace-only values that slip past {@code @Size(min = 1)}. The {@code address} is
 * checked in its normalized form (see {@link AddressNormalizer}), so a value blank after
 * normalization is rejected too. Publishes the validated body for {@link BuildOwner}.
 */
@Validated
public class ValidateOwnerFields {

    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        requireText(missing, "firstName", request.getFirstName());
        requireText(missing, "lastName", request.getLastName());
        requireText(missing, "address", AddressNormalizer.normalize(request.getAddress()));
        requireText(missing, "city", request.getCity());
        requireText(missing, "telephone", request.getTelephone());
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static void requireText(List<String> missing, String field, String value) {
        if (value == null || value.isBlank()) {
            missing.add(field);
        }
    }
}
===== AddressNormalizer.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical form for an owner {@code address}, shared by every step that stores or compares
 * one. Normalization trims and collapses internal whitespace runs to a single space,
 * upper-cases, and expands common street-type abbreviations as whole words
 * ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD}, {@code AVE}&rarr;{@code AVENUE}).
 * A {@code null} or whitespace-only value normalizes to the empty string.
 *
 * <p>The function is idempotent: normalizing an already-normalized address returns it
 * unchanged, so it is safe to apply again when comparing against stored owners.
 */
final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS =
            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            String expanded = ABBREVIATIONS.get(tokens[i]);
            sb.append(expanded != null ? expanded : tokens[i]);
        }
        return sb.toString();
    }
}
